/* Autonomous Studio — data is read from site/veri (generated by build.py). */
async function j(p){ try{ const r=await fetch("veri/"+p); return r.ok? r.json():null }catch(e){ return null } }
async function t(p){ try{ const r=await fetch("veri/"+p); return r.ok? r.text():null }catch(e){ return null } }
const el=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

async function common(){
  const a=await t("name.txt");
  if(a&&a.trim()&&el("company-name")) el("company-name").textContent=a.trim();
}

async function dashboard(){
  if(!el("olaylar")) return;
  const g=await j("gunluk.json");
  if(g&&g.length) el("olaylar").innerHTML=g.slice(0,12).map(x=>
    `<div class="satir"><span>${esc(x.mesaj)}</span><span class="soluk">${esc(x.tarih)}</span></div>`).join("");
  const m=await j("manifest.json"); if(!m) return;
  const hall=m.dosyalar.filter(d=>d.startsWith("hallway/")).sort().slice(-6);
  if(hall.length){
    const lines=await Promise.all(hall.map(k=>t(k)));
    el("koridor").innerHTML=lines.filter(Boolean).map(s=>`<div class="satir"><span>${esc(s.trim())}</span></div>`).join("");
  }
}

async function predictions(){
  if(!el("lig-tablo")) return;
  const lig=await j("data/league.json");
  if(lig){
    const p=Object.entries(lig.personas).sort((a,b)=>b[1].points-a[1].points);
    el("lig-tablo").innerHTML="<table><tr><th>Persona</th><th>Points</th><th>Exact scores</th><th>Correct outcomes</th><th>Weeks</th></tr>"+
      p.map(([n,k])=>`<tr><td>${esc(n)}</td><td>${k.points}</td><td>${k.exact}</td><td>${k.outcome}</td><td>${k.weeks}</td></tr>`).join("")+"</table>";
    if(window.Chart&&el("lig-grafik")) new Chart(el("lig-grafik"),{type:"bar",
      data:{labels:p.map(x=>x[0]),datasets:[{label:"points",data:p.map(x=>x[1].points),backgroundColor:"#5b8cff"}]},
      options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{color:"#9aa3b5"}},x:{ticks:{color:"#9aa3b5"}}}}});
  }
  const m=await j("manifest.json"); if(!m) return;
  const th=m.dosyalar.filter(d=>/^data\/predictions\/.+\.json$/.test(d)).sort();
  if(!th.length) return;
  const weeks=[...new Set(th.map(d=>d.split("/").pop().replace(".json","")))].sort();
  const last=weeks[weeks.length-1];
  let html="";
  for(const d of th.filter(x=>x.endsWith(last+".json"))){
    const persona=d.split("/")[2], data=await j(d); if(!data) continue;
    html+=`<h3 class="soluk" style="margin-top:14px">${esc(persona)} — ${esc(last)}</h3>`+
      data.map(x=>`<div class="satir"><span>${esc(x.home)} ${esc(x.score)} ${esc(x.away)}</span><span class="soluk">${esc(x.reasoning)}</span></div>`).join("");
  }
  if(html) el("tahminler").innerHTML=html;
  el("arsiv").innerHTML=weeks.map(h=>`<span class="rozet" style="margin-right:8px">${esc(h)}</span>`).join("")||el("arsiv").innerHTML;
}

async function office(){
  if(!el("kadro")) return;
  const r=await j("roster.json");
  if(r) el("kadro").innerHTML=r.map(a=>
    `<div class="kart"><h3>${esc(a.ad)}</h3><p>${esc(a.rol)} · shifts: ${a.gunler.join(", ")}</p>
     <p><a href="#" data-prompt="${esc(a.id)}">view prompt</a></p><pre hidden id="p-${esc(a.id)}"></pre></div>`).join("");
  document.querySelectorAll("[data-prompt]").forEach(x=>x.addEventListener("click",async e=>{
    e.preventDefault(); const id=x.dataset.prompt, pre=el("p-"+id);
    if(!pre.hidden){pre.hidden=true;return}
    pre.textContent=(await t("prompts/"+id+".md"))||"prompt unavailable"; pre.hidden=false;
  }));
  const m=await j("manifest.json"); if(!m) return;
  const mins=m.dosyalar.filter(d=>d.startsWith("minutes/")).sort().reverse().slice(0,20);
  if(mins.length){
    el("tutanaklar").innerHTML=mins.map(d=>`<div class="satir"><a href="#" data-min="${esc(d)}">${esc(d.replace("minutes/",""))}</a></div><pre hidden id="t-${esc(d)}"></pre>`).join("");
    document.querySelectorAll("[data-min]").forEach(x=>x.addEventListener("click",async e=>{
      e.preventDefault(); const d=x.dataset.min, pre=document.getElementById("t-"+d);
      if(!pre.hidden){pre.hidden=true;return}
      pre.textContent=(await t(d))||"unavailable"; pre.hidden=false;
    }));
  }
}

async function changelog(){
  if(!el("gunluk")) return;
  const g=await j("gunluk.json");
  if(g&&g.length) el("gunluk").innerHTML="<table><tr><th>Date</th><th>Change</th></tr>"+
    g.map(x=>`<tr><td class="soluk">${esc(x.tarih)}</td><td>${esc(x.mesaj)}</td></tr>`).join("")+"</table>";
}

common(); dashboard(); predictions(); office(); changelog();
